            item.Initialize(def, ProcessState.Raw);
            item.PlaceOnGround(new Vector3(0, 0, 0));
            Assume.That(item.IsLoose, Is.True, "준비 단계 확인 실패(검증 대상이 아니라 시험 준비가 잘못됨): 재료가 바닥에 놓여 IsLoose 상태여야 함");
            var dt = GenHelpers.MeasureDt();
            GenHelpers.Invoke(item, "Update");
            Assert.That(item.IsSpoiling, Is.True, "근거: 손/설비 보관 ──내려놓기──> 바닥(감소 시작)");
        }
    }
}
